    "PAYHOOK_ENDPOINT": "https://api.payments.example/v1",
    "PAYHOOK_TIMEOUT": "10",
    "PAYHOOK_REGION": "eu",
}

DOTENV_PATH = ".env"

_EXPORT_RE = re.compile(r"^export\s+")
_INLINE_COMMENT_RE = re.compile(r"\s+#.*$")


def _parse_dotenv_line(line):
    """Return (key, value) for one .env line, or None if it sets nothing."""
    line = line.strip()
    if not line or line.startswith("#"):
        return None
    line = _EXPORT_RE.sub("", line, count=1)
    key, sep, value = line.partition("=")
    key = key.strip()
    if not sep or not key:
        return None
    value = value.strip()
    if value[:1] in ("'", '"'):
        # Quoted: the value runs to the matching closing quote; anything
        # after it (such as a trailing comment) is ignored.
        end = value.find(value[0], 1)
        if end != -1:
            value = value[1:end]
        else:
            value = value[1:]
    else:
        # Unquoted: a " #" starts a comment. A bare "#" stays part of the value.
        value = _INLINE_COMMENT_RE.sub("", value)
    return key, value


def read_dotenv(path):
    values = {}
    if not os.path.exists(path):
        return values
    with open(path, encoding="utf-8-sig") as handle:
        for line in handle:
            parsed = _parse_dotenv_line(line)
            if parsed is not None:
                key, value = parsed
                values[key] = value
    return values


